import java.util.Scanner;
public class p723b {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String s = in.next();
        int prev = -1;
        int maxOutside = 0;
        int insideWords = 0;
        boolean inside = false;
        int index = 0;
        for (char c : s.toCharArray()) {
            int segmentLength = index - prev - 1;
            switch (c) {
                case '_':
                    if (!inside) {
                        if (segmentLength > maxOutside) maxOutside = segmentLength;
                    } else if (segmentLength > 0) {
                        insideWords++;
                    }
                    break;
                case '(':
                    inside = true;
                    if (segmentLength > maxOutside) maxOutside = segmentLength;
                    break;
                case ')':
                    inside = false;
                    if (segmentLength > 0) insideWords++;
                    break;
                default:
                    break;
            }
            if (c == '_' || c == '(' || c == ')') {
                prev = index;
            }
            index++;
        }
        int tailLength = s.length() - prev - 1;
        if (tailLength > maxOutside) maxOutside = tailLength;
        System.out.println(maxOutside + " " + insideWords);
    }
}
